def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h - 1):
        for c in range(w - 1):
            if not all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                continue
            # Four diagonally adjacent colors cycle clockwise around the 2x2.
            # Each colored corner launches a ray outward from the corresponding corner.
            points = [(r-1,c-1), (r-1,c+2), (r+2,c-1), (r+2,c+2)]  # UL, UR, LL, LR
            colors = [grid[rr][cc] for rr,cc in points]
            ray_colors = [colors[2], colors[0], colors[3], colors[1]]
            directions = [(-1,-1), (-1,1), (1,-1), (1,1)]
            for (rr,cc), color, (dr,dc) in zip(points, ray_colors, directions):
                if not (0 <= rr < h and 0 <= cc < w):
                    continue
                while 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out
